'use client';

import { useCallback, useEffect, useState } from 'react';

import { Sheet, SheetContent, SheetTitle } from '@/registry/ndeko/ui/sheet';

import { AppSidebar, type PageCounts, type SidebarMode } from './app-sidebar';
import {
  CURRENT_USER_ID,
  EMPTY_PAGES,
  INITIAL_ROLES,
  LABELS,
  NAV_GROUPS,
  NOTIFICATIONS,
  PEOPLE,
  PRODUCT_TEAM,
  PROJECTS,
  SETTINGS_GROUPS,
  STATUSES,
  TASKS,
  WORKSPACES,
  personOf,
  type AppPageId,
  type NavGroup,
  type NavItem,
  type Notification,
  type PageId,
  type Project,
  type SettingsPageId,
  type Task,
} from './data';
import {
  EmptyPageView,
  InboxPage,
  MembersPage,
  ProjectsPage,
  TaskListPage,
} from './page-views';
import type { CreateKind } from './quick-create-menu';
import { CommandPalette } from './search-palette';
import { SettingsView, type SettingsState } from './settings-pages';
import { TopBar } from './top-bar';

const NAV_ITEMS = [...NAV_GROUPS, ...SETTINGS_GROUPS].flatMap(
  (group) => group.items
);

const FIRST_TASK_NUMBER = 100;

const SETTINGS_ANCESTOR = 'Settings';

const INITIAL_USER = personOf(CURRENT_USER_ID);

const INITIAL_SETTINGS: SettingsState = {
  fullName: INITIAL_USER.name,
  email: 'amara@lattice.example',
  title: INITIAL_USER.role,
  timeZone: 'Africa/Lagos',
  weekStart: 'monday',
  remindToTrack: true,
  stopWhenIdle: false,
  showSeconds: false,
  mailAssignments: true,
  mailMentions: true,
  mailWeeklySummary: false,
  appComments: true,
  appStatusChanges: false,
  teamName: PRODUCT_TEAM.name,
  teamKey: 'LAT',
  visibility: 'private',
  roles: INITIAL_ROLES,
  statuses: STATUSES,
  labels: LABELS,
};

function isSettingsPage(pageId: PageId): pageId is SettingsPageId {
  return pageId.startsWith('settings-');
}

function navItemOf(pageId: PageId): NavItem {
  const item = NAV_ITEMS.find((candidate) => candidate.id === pageId);
  if (item) {
    return item;
  }
  return NAV_ITEMS[0];
}

function ancestorOf(pageId: PageId, workspaceName: string, teamName: string) {
  if (isSettingsPage(pageId)) {
    return SETTINGS_ANCESTOR;
  }
  const group = NAV_GROUPS.find((candidate) =>
    candidate.items.some((item) => item.id === pageId)
  );
  if (group?.team) {
    return teamName;
  }
  if (group?.label) {
    return workspaceName;
  }
  return undefined;
}

function withTeamName(groups: NavGroup[], teamName: string): NavGroup[] {
  return groups.map((group) => {
    if (!group.team) {
      return group;
    }
    const team = { ...group.team, name: teamName };
    return { ...group, team };
  });
}

function workspaceOf(workspaceId: string) {
  const workspace = WORKSPACES.find(
    (candidate) => candidate.id === workspaceId
  );
  if (workspace) {
    return workspace;
  }
  return WORKSPACES[0];
}

function numberOf(task: Task) {
  const digits = task.number.replace(/\D/g, '');
  return Number(digits);
}

function draftTaskAfter(tasks: Task[]): Task {
  const numbers = tasks.map(numberOf);
  const nextNumber = Math.max(FIRST_TASK_NUMBER, ...numbers) + 1;
  return {
    id: `task-${nextNumber}`,
    number: `LAT-${nextNumber}`,
    title: 'Untitled task',
    projectId: 'onboarding',
    assigneeId: CURRENT_USER_ID,
    due: 'No date',
    isDone: false,
  };
}

function draftProjectAfter(projects: Project[]): Project {
  const draftNumber = projects.length + 1;
  return {
    id: `project-${draftNumber}`,
    name: 'Untitled project',
    color: 'var(--muted-foreground)',
    leadId: CURRENT_USER_ID,
  };
}

function isTypingTarget(target: EventTarget | null) {
  if (!(target instanceof HTMLElement)) {
    return false;
  }
  const isField = target.matches('input, textarea, select');
  return isField || target.isContentEditable;
}

function isPaletteShortcut(event: KeyboardEvent) {
  const isKKey = event.key.toLowerCase() === 'k';
  const hasModifier = event.metaKey || event.ctrlKey;
  return isKKey && hasModifier;
}

function isCreateShortcut(event: KeyboardEvent) {
  const isCKey = event.key.toLowerCase() === 'c';
  const hasModifier = event.metaKey || event.ctrlKey || event.altKey;
  const isTyping = isTypingTarget(event.target);
  return isCKey && !hasModifier && !isTyping;
}

function emptyPageOf(pageId: PageId) {
  if (isSettingsPage(pageId)) {
    return undefined;
  }
  return EMPTY_PAGES[pageId];
}

function modeOf(pageId: PageId): SidebarMode {
  if (isSettingsPage(pageId)) {
    return 'settings';
  }
  return 'app';
}

export default function AppShells03() {
  const [activePageId, setActivePageId] = useState<PageId>('settings-profile');
  const [lastAppPageId, setLastAppPageId] = useState<AppPageId>('my-tasks');
  const [workspaceId, setWorkspaceId] = useState(WORKSPACES[0].id);
  const [isNavigationOpen, setIsNavigationOpen] = useState(false);
  const [isPaletteOpen, setIsPaletteOpen] = useState(false);
  const [tasks, setTasks] = useState<Task[]>(TASKS);
  const [projects, setProjects] = useState<Project[]>(PROJECTS);
  const [notifications, setNotifications] =
    useState<Notification[]>(NOTIFICATIONS);
  const [settings, setSettings] = useState<SettingsState>(INITIAL_SETTINGS);

  const mode = modeOf(activePageId);
  const workspace = workspaceOf(workspaceId);
  const appGroups = withTeamName(NAV_GROUPS, settings.teamName);
  const settingsGroups = withTeamName(SETTINGS_GROUPS, settings.teamName);
  let sidebarGroups = appGroups;
  if (mode === 'settings') {
    sidebarGroups = settingsGroups;
  }
  const activePage = navItemOf(activePageId);
  const ancestor = ancestorOf(activePageId, workspace.name, settings.teamName);
  const currentUser = {
    ...INITIAL_USER,
    name: settings.fullName,
    role: settings.title,
  };
  const myTasks = tasks.filter((task) => task.assigneeId === CURRENT_USER_ID);
  const myOpenTasks = myTasks.filter((task) => !task.isDone);
  const teamOpenTasks = tasks.filter((task) => !task.isDone);
  const unreadNotifications = notifications.filter((note) => note.isUnread);
  const counts: PageCounts = {
    inbox: unreadNotifications.length,
    'my-tasks': myOpenTasks.length,
    'team-tasks': teamOpenTasks.length,
  };

  const createTask = useCallback(() => {
    setTasks((previous) => {
      const draft = draftTaskAfter(previous);
      return [draft, ...previous];
    });
    setActivePageId('my-tasks');
    setLastAppPageId('my-tasks');
  }, []);

  useEffect(() => {
    function handleKeyDown(event: KeyboardEvent) {
      if (isPaletteShortcut(event)) {
        event.preventDefault();
        setIsPaletteOpen((isOpen) => !isOpen);
        return;
      }
      if (isCreateShortcut(event)) {
        event.preventDefault();
        createTask();
      }
    }

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [createTask]);

  function navigate(pageId: PageId) {
    setActivePageId(pageId);
    setIsNavigationOpen(false);
    if (!isSettingsPage(pageId)) {
      setLastAppPageId(pageId);
    }
  }

  function backToApp() {
    navigate(lastAppPageId);
  }

  function create(kind: CreateKind) {
    setIsNavigationOpen(false);
    if (kind === 'task') {
      createTask();
      return;
    }
    if (kind === 'project') {
      setProjects((previous) => {
        const draft = draftProjectAfter(previous);
        return [...previous, draft];
      });
      navigate('projects');
      return;
    }
    navigate('settings-team-members');
  }

  function createProject() {
    create('project');
  }

  function openSearch() {
    setIsNavigationOpen(false);
    setIsPaletteOpen(true);
  }

  function openNavigation() {
    setIsNavigationOpen(true);
  }

  function changeSettings(patch: Partial<SettingsState>) {
    setSettings((previous) => ({ ...previous, ...patch }));
  }

  function toggleTask(taskId: string) {
    setTasks((previous) =>
      previous.map((task) => {
        if (task.id !== taskId) {
          return task;
        }
        return { ...task, isDone: !task.isDone };
      })
    );
  }

  function readNotification(notificationId: string) {
    setNotifications((previous) =>
      previous.map((note) => {
        if (note.id !== notificationId) {
          return note;
        }
        return { ...note, isUnread: false };
      })
    );
  }

  function readAllNotifications() {
    setNotifications((previous) =>
      previous.map((note) => ({ ...note, isUnread: false }))
    );
  }

  const sidebarProps = {
    mode,
    workspaces: WORKSPACES,
    workspace,
    onWorkspaceChange: setWorkspaceId,
    groups: sidebarGroups,
    activePageId,
    counts,
    person: currentUser,
    onNavigate: navigate,
    onBackToApp: backToApp,
    onOpenSettings: navigate,
    onOpenSearch: openSearch,
    onCreate: create,
  };
  const emptyPage = emptyPageOf(activePageId);

  return (
    <div className='bg-sidebar text-foreground flex h-dvh min-h-0 w-full md:p-2'>
      <aside
        aria-label='Sidebar'
        className='hidden w-60 shrink-0 pr-2 md:block'
      >
        <AppSidebar {...sidebarProps} />
      </aside>
      <Sheet open={isNavigationOpen} onOpenChange={setIsNavigationOpen}>
        <SheetContent
          side='left'
          showCloseButton={false}
          className='bg-sidebar w-72 gap-0 p-2'
        >
          <SheetTitle className='sr-only'>Navigation</SheetTitle>
          <AppSidebar {...sidebarProps} />
        </SheetContent>
      </Sheet>
      <main className='bg-background md:hairline-ring md:ring-border flex min-w-0 flex-1 flex-col overflow-clip md:rounded-xl md:shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
        <TopBar
          page={activePage}
          ancestor={ancestor}
          people={PEOPLE}
          onOpenNavigation={openNavigation}
        />
        {isSettingsPage(activePageId) && (
          <SettingsView
            pageId={activePageId}
            settings={settings}
            onChange={changeSettings}
          />
        )}
        {activePageId === 'inbox' && (
          <InboxPage
            notifications={notifications}
            onRead={readNotification}
            onReadAll={readAllNotifications}
          />
        )}
        {activePageId === 'my-tasks' && (
          <TaskListPage
            key='my-tasks'
            title='My tasks'
            tasks={myTasks}
            showAssignee={false}
            onToggleTask={toggleTask}
            onCreateTask={createTask}
          />
        )}
        {activePageId === 'team-tasks' && (
          <TaskListPage
            key='team-tasks'
            title={`${settings.teamName} tasks`}
            tasks={tasks}
            showAssignee
            onToggleTask={toggleTask}
            onCreateTask={createTask}
          />
        )}
        {activePageId === 'projects' && (
          <ProjectsPage
            projects={projects}
            tasks={tasks}
            onCreateProject={createProject}
          />
        )}
        {activePageId === 'members' && <MembersPage people={PEOPLE} />}
        {emptyPage && (
          <EmptyPageView
            title={activePage.label}
            meta={`${settings.teamName} team`}
            icon={activePage.icon}
            page={emptyPage}
          />
        )}
      </main>
      <CommandPalette
        open={isPaletteOpen}
        onOpenChange={setIsPaletteOpen}
        groups={appGroups}
        onNavigate={navigate}
        onCreateTask={createTask}
      />
    </div>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useId } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { ArrowLeftIcon } from '@/registry/ndeko/lib/icons';

import { AccountMenu } from './account-menu';
import type {
  NavGroup,
  NavItem,
  PageId,
  Person,
  SettingsPageId,
  Workspace,
} from './data';
import { QuickCreateMenu, type CreateKind } from './quick-create-menu';
import { SearchTrigger } from './search-palette';
import { EntityTile, NAV_ROW, NavRow } from './sidebar-parts';
import { WorkspaceSwitcher } from './workspace-switcher';

export type PageCounts = Partial<Record<PageId, number>>;

export type SidebarMode = 'app' | 'settings';

const MODE_SHIFT_PX = 12;

const MODE_TRANSITION: Transition = {
  duration: 0.22,
  ease: [0.23, 1, 0.32, 1],
};

const MODE_VARIANTS: Variants = {
  enter: (direction: number) => {
    const offset = direction * MODE_SHIFT_PX;
    return { opacity: 0, x: offset };
  },
  visible: { opacity: 1, x: 0 },
  exit: (direction: number) => {
    const offset = direction * MODE_SHIFT_PX;
    return { opacity: 0, x: -offset };
  },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

function modeVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return MODE_VARIANTS;
}

function navLabelOf(mode: SidebarMode) {
  if (mode === 'settings') {
    return 'Settings';
  }
  return 'Main';
}

function directionOf(mode: SidebarMode) {
  if (mode === 'settings') {
    return 1;
  }
  return -1;
}

type AppSidebarProps = {
  mode: SidebarMode;
  workspaces: Workspace[];
  workspace: Workspace;
  onWorkspaceChange: (workspaceId: string) => void;
  groups: NavGroup[];
  activePageId: PageId;
  counts: PageCounts;
  person: Person;
  onNavigate: (pageId: PageId) => void;
  onBackToApp: () => void;
  onOpenSettings: (pageId: SettingsPageId) => void;
  onOpenSearch: () => void;
  onCreate: (kind: CreateKind) => void;
};

function GroupLabel({ group }: { group: NavGroup }) {
  if (group.team) {
    return (
      <p className='text-muted-foreground flex h-6 items-center gap-2 px-2 text-xs font-medium'>
        <EntityTile entity={group.team} size='xs' />
        <span className='truncate'>{group.team.name}</span>
      </p>
    );
  }
  if (group.label) {
    return (
      <p className='text-muted-foreground flex h-6 items-center px-2 text-xs font-medium'>
        {group.label}
      </p>
    );
  }
  return null;
}

export function AppSidebar({
  mode,
  workspaces,
  workspace,
  onWorkspaceChange,
  groups,
  activePageId,
  counts,
  person,
  onNavigate,
  onBackToApp,
  onOpenSettings,
  onOpenSearch,
  onCreate,
}: AppSidebarProps) {
  const indicatorId = useId();
  const shouldReduceMotion = usePrefersReducedMotion();
  const modeVariants = modeVariantsOf(shouldReduceMotion);
  const direction = directionOf(mode);
  const isSettingsMode = mode === 'settings';
  const modeIndicatorId = `${indicatorId}-${mode}`;

  function selectItem(item: NavItem) {
    onNavigate(item.id);
  }

  function openWorkspaceSettings() {
    onOpenSettings('settings-team-general');
  }

  return (
    <div className='flex h-full min-h-0 flex-col gap-3'>
      <div className='flex flex-col gap-2'>
        <WorkspaceSwitcher
          workspaces={workspaces}
          current={workspace}
          onSelect={onWorkspaceChange}
          onOpenSettings={openWorkspaceSettings}
        />
        <div className='flex items-center gap-2'>
          <SearchTrigger onOpen={onOpenSearch} />
          <QuickCreateMenu onCreate={onCreate} />
        </div>
      </div>
      <div className='-mx-2 flex min-h-0 flex-1 flex-col overflow-x-hidden overflow-y-auto px-2'>
        <AnimatePresence mode='popLayout' initial={false} custom={direction}>
          <motion.nav
            key={mode}
            custom={direction}
            variants={modeVariants}
            initial='enter'
            animate='visible'
            exit='exit'
            transition={MODE_TRANSITION}
            aria-label={navLabelOf(mode)}
            className='flex flex-col gap-4'
          >
            {isSettingsMode && (
              <button type='button' onClick={onBackToApp} className={NAV_ROW}>
                <ArrowLeftIcon />
                <span className='relative min-w-0 flex-1 truncate'>
                  Back to app
                </span>
              </button>
            )}
            {groups.map((group) => (
              <div key={group.id} className='flex flex-col gap-0.5'>
                <GroupLabel group={group} />
                <ul className='flex flex-col gap-px'>
                  {group.items.map((item) => (
                    <NavRow
                      key={item.id}
                      item={item}
                      isActive={item.id === activePageId}
                      indicatorId={modeIndicatorId}
                      count={counts[item.id]}
                      onSelect={selectItem}
                    />
                  ))}
                </ul>
              </div>
            ))}
          </motion.nav>
        </AnimatePresence>
      </div>
      <AccountMenu person={person} onOpenSettings={onOpenSettings} />
    </div>
  );
}

'use client';

import { motion, type Transition } from 'motion/react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';

import type { Entity, NavItem, Person } from './data';

export const NAV_ROW = [
  'relative flex h-7 w-full min-w-0 items-center gap-2 rounded-md px-2 text-left text-[13px] font-medium text-foreground outline-none',
  'transition-colors duration-150 hover:bg-foreground/5 focus-visible:ring-[3px] focus-visible:ring-ring/25',
  "[&_svg]:pointer-events-none [&_svg]:relative [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 [&_svg:not([class*='text-'])]:text-muted-foreground",
].join(' ');

const INDICATOR_TRAVEL: Transition = {
  duration: 0.25,
  ease: [0.77, 0, 0.175, 1],
};

const INSTANT: Transition = { duration: 0 };

function travelOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return INDICATOR_TRAVEL;
}

/** The one highlight of the active row. It travels from the old row to the new one. */
export function ActiveRowIndicator({ layoutId }: { layoutId: string }) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <motion.span
      aria-hidden='true'
      layoutId={layoutId}
      transition={travelOf(shouldReduceMotion)}
      className='bg-foreground/[0.07] absolute inset-0 rounded-md'
    />
  );
}

const TILE_SIZE = {
  xs: 'size-4 rounded-[4px]',
  sm: 'size-5 rounded-[5px]',
  md: 'size-6 rounded-md',
} as const;

/** The picture of a team: a gradient drawn from its name, in its colour. */
export function EntityTile({
  entity,
  size = 'md',
  className,
}: {
  entity: Entity;
  size?: keyof typeof TILE_SIZE;
  className?: string;
}) {
  return (
    <MeshTile
      seed={entity.name}
      color={entity.color}
      className={cn(TILE_SIZE[size], className)}
    />
  );
}

export function PersonAvatar({
  person,
  className,
}: {
  person: Person;
  className?: string;
}) {
  return <Avatar className={className} seed={person.name} />;
}

export function ariaCurrentOf(isActive: boolean) {
  if (isActive) {
    return 'page' as const;
  }
  return undefined;
}

type NavRowProps = {
  item: NavItem;
  isActive: boolean;
  indicatorId: string;
  count?: number;
  onSelect: (item: NavItem) => void;
};

export function NavRow({
  item,
  isActive,
  indicatorId,
  count = 0,
  onSelect,
}: NavRowProps) {
  const hasCount = count > 0;
  const ItemIcon = item.icon;
  const ariaCurrent = ariaCurrentOf(isActive);

  function selectItem() {
    onSelect(item);
  }

  return (
    <li>
      <button
        type='button'
        aria-current={ariaCurrent}
        onClick={selectItem}
        className={NAV_ROW}
      >
        {isActive && <ActiveRowIndicator layoutId={indicatorId} />}
        <ItemIcon />
        <span className='relative min-w-0 flex-1 truncate'>{item.label}</span>
        {hasCount && (
          <MotionNumber
            value={count}
            className='text-muted-foreground text-xs font-normal'
          />
        )}
      </button>
    </li>
  );
}

'use client';

import {
  ChevronsUpDownIcon,
  PlusIcon,
  SettingsIcon,
} from '@/registry/ndeko/lib/icons';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';
import { Kbd } from '@/registry/ndeko/ui/kbd';

import type { Workspace } from './data';

const TRIGGER = [
  'flex h-9 min-w-0 flex-1 items-center gap-2 rounded-md px-1.5 text-left outline-none',
  'transition-colors duration-150 hover:bg-foreground/5 data-popup-open:bg-foreground/5 focus-visible:ring-[3px] focus-visible:ring-ring/25',
].join(' ');

function memberCountLabelOf(count: number) {
  if (count === 1) {
    return '1 member';
  }
  return `${count} members`;
}

type WorkspaceSwitcherProps = {
  workspaces: Workspace[];
  current: Workspace;
  onSelect: (workspaceId: string) => void;
  onOpenSettings: () => void;
};

export function WorkspaceSwitcher({
  workspaces,
  current,
  onSelect,
  onOpenSettings,
}: WorkspaceSwitcherProps) {
  function selectWorkspace(value: unknown) {
    if (typeof value === 'string') {
      onSelect(value);
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button
            type='button'
            aria-label={`Workspace: ${current.name}`}
            className={TRIGGER}
          />
        }
      >
        <CompanyMark seed={current.name} className='size-6 rounded-md' />
        <span className='min-w-0 flex-1 truncate text-[13px] font-semibold'>
          {current.name}
        </span>
        <ChevronsUpDownIcon className='text-muted-foreground size-3.5 shrink-0' />
      </DropdownMenuTrigger>
      <DropdownMenuContent className='w-64'>
        <DropdownMenuLabel>Workspaces</DropdownMenuLabel>
        <DropdownMenuRadioGroup
          value={current.id}
          onValueChange={selectWorkspace}
        >
          {workspaces.map((workspace) => (
            <DropdownMenuRadioItem
              key={workspace.id}
              value={workspace.id}
              closeOnClick
              className='h-9'
            >
              <CompanyMark seed={workspace.name} />
              <span className='min-w-0 flex-1 truncate'>{workspace.name}</span>
              <Kbd aria-hidden='true'>{workspace.memberCount}</Kbd>
              <span className='sr-only'>
                {memberCountLabelOf(workspace.memberCount)}
              </span>
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
        <DropdownMenuSeparator />
        <DropdownMenuItem onClick={onOpenSettings}>
          <SettingsIcon />
          Settings
        </DropdownMenuItem>
        <DropdownMenuItem>
          <PlusIcon />
          Add workspace
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

'use client';

import { CircleCheckIcon, SearchIcon } from '@/registry/ndeko/lib/icons';
import { CONTROL_RECIPE } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
