type CommandPaletteProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  groups: NavGroup[];
  onNavigate: (pageId: PageId) => void;
  onCreateTask: () => void;
};

export function CommandPalette({
  open,
  onOpenChange,
  groups,
  onNavigate,
  onCreateTask,
}: CommandPaletteProps) {
  function closePalette() {
    onOpenChange(false);
  }

  function createTask() {
    closePalette();
    onCreateTask();
  }

  return (
    <CommandDialog
      open={open}
      onOpenChange={onOpenChange}
      title='Search'
      description='Go to a page or run an action'
    >
      <CommandInput placeholder='Go to a page or run an action' />
      <CommandList>
        <CommandEmpty>Nothing matches. Try the name of a page.</CommandEmpty>
        <CommandGroup heading='Actions'>
          <CommandItem onSelect={createTask}>
            <CircleCheckIcon />
            New task
            <CommandShortcut>C</CommandShortcut>
          </CommandItem>
        </CommandGroup>
        {groups.map((group) => (
          <CommandGroup key={group.id} heading={headingOf(group)}>
            {group.items.map((item) => {
              const ItemIcon = item.icon;

              function goToPage() {
                closePalette();
                onNavigate(item.id);
              }

              return (
                <CommandItem
                  key={item.id}
                  value={`${group.id} ${item.label}`}
                  onSelect={goToPage}
                >
                  <ItemIcon />
                  {item.label}
                </CommandItem>
              );
            })}
          </CommandGroup>
        ))}
      </CommandList>
    </CommandDialog>
  );
}

