type DangerRowProps = {
  label: string;
  line: string;
  dialogTitle: string;
  actionLabel: string;
  objectName: string;
  consequences: string[];
  scheduledLine: string;
};

export function DangerRow({
  label,
  line,
  dialogTitle,
  actionLabel,
  objectName,
  consequences,
  scheduledLine,
}: DangerRowProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [typedName, setTypedName] = useState('');
  const [isScheduled, setIsScheduled] = useState(false);
  const confirmFieldId = useId();
  const isNameTyped = typedName.trim() === objectName;

  function openConfirmation() {
    setTypedName('');
    setIsOpen(true);
  }

  function changeTypedName(event: React.ChangeEvent<HTMLInputElement>) {
    setTypedName(event.target.value);
  }

  function confirmDeletion() {
    setIsScheduled(true);
  }

  function cancelDeletion() {
    setIsScheduled(false);
  }

  if (isScheduled) {
    return (
      <SettingsRow label={label} line={scheduledLine}>
        <Button variant='outline' onClick={cancelDeletion}>
          Cancel deletion
        </Button>
      </SettingsRow>
    );
  }

  return (
    <SettingsRow label={label} line={line}>
      <Button
        variant='outline'
        onClick={openConfirmation}
        className='text-destructive-ink'
      >
        {actionLabel}
      </Button>
      <AlertDialog open={isOpen} onOpenChange={setIsOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{dialogTitle}</AlertDialogTitle>
            <AlertDialogDescription>
              This cannot be undone once the grace period ends
            </AlertDialogDescription>
          </AlertDialogHeader>
          <ul className='bg-foreground/[0.03] hairline-divide-y divide-border flex flex-col rounded-lg'>
            {consequences.map((consequence) => (
              <li key={consequence} className='px-3 py-2 text-[13px]'>
                {consequence}
              </li>
            ))}
          </ul>
          <div className='flex flex-col gap-1.5'>
            <label
              htmlFor={confirmFieldId}
              className='text-muted-foreground text-xs'
            >
              Type{' '}
              <span className='text-foreground font-medium'>{objectName}</span>{' '}
              to confirm
            </label>
            <Input
              id={confirmFieldId}
              value={typedName}
              autoComplete='off'
              onChange={changeTypedName}
            />
          </div>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep it</AlertDialogCancel>
            <AlertDialogAction
              variant='destructive'
              disabled={!isNameTyped}
              onClick={confirmDeletion}
            >
              {actionLabel}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </SettingsRow>
  );
}

