      <PropertyList
        kind='status'
        values={settings.statuses}
        onAdd={addStatus}
      />
    </SettingsPage>
  );
}

function LabelsPage({ settings, onChange }: PageProps) {
  function addLabel(name: string) {
    const added = newValueOf(name, settings.labels);
