export function personOf(personId: string) {
  const person = PEOPLE.find((candidate) => candidate.id === personId);
  if (person) {
    return person;
  }
  return PEOPLE[0];
}

export function projectOf(projectId: string) {
  const project = PROJECTS.find((candidate) => candidate.id === projectId);
  if (project) {
    return project;
  }
  return PROJECTS[0];
}

